package cli

import (
	"bufio"
	"context"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"

	apiclientgen "github.com/discobox-ai/discobox/api/gen"
	apimodel "github.com/discobox-ai/discobox/api/model"
	"github.com/discobox-ai/discobox/internal/filelock"
)

// The written artifacts live beside the generated key, under the state
// directory of whichever ssh reads them, and that ssh's ~/.ssh/config gains one
// line per server/project: an Include pointing at that namespace's file. Keeping the
// generated files out of ~/.ssh means this command never has to parse, merge
// into, or risk mangling a config the user maintains by hand — it owns each
// project's files outright and rewrites them wholesale. Where they land, and
// how they are spelled once they are there, is sshTarget's answer: on WSL the
// ssh that reads them can be the Windows one.
//
// The files are per server/project rather than one merged config because a run only
// ever knows about one project: writing a shared file would delete the stanzas
// of every other project each time, and two projects can live on different
// servers with different host keys and addresses.

type sshConfigRender struct {
	namespace string
	sandboxes []apimodel.Sandbox

	// proxyCommand carries the connection. Nothing here names an address: the
	// server binds no SSH port, so the stanzas reach it the same way every
	// other request does (ADR 0057).
	proxyCommand string

	// hostKeyAlias is what the stanzas verify the host key under, and so the
	// host field of the matching known_hosts line. Without an address there is
	// nothing for ssh to derive one from.
	hostKeyAlias string

	identityFile   string
	knownHostsFile string
}

// renderSSHConfig builds the Host stanzas. It is shared by both output modes so
// what gets written is exactly what would have been printed, apart from the
// UserKnownHostsFile only the written form can honestly name.
func renderSSHConfig(in sshConfigRender) string {
	var out strings.Builder
	for i, sandbox := range in.sandboxes {
		fmt.Fprintf(&out, "Host %s\n", strings.Join(sshConfigHostPatterns(in.namespace, sandbox.ID), " "))
		// No HostName and no Port: there is no address to dial. ssh runs the
		// ProxyCommand and speaks its protocol over its stdio. The whole line
		// is escaped rather than the endpoint alone, since the executable's
		// path is as free to contain a percent sign as the endpoint is.
		fmt.Fprintf(&out, "    ProxyCommand %s\n", escapeSSHPercent(in.proxyCommand))
		fmt.Fprintf(&out, "    User %s\n", sandbox.ID)
		fmt.Fprintf(&out, "    IdentityFile %s\n", sshConfigPath(in.identityFile))
		// Without IdentitiesOnly, ssh offers every agent key before this one
		// and can exhaust MaxAuthTries before reaching it.
		fmt.Fprintf(&out, "    IdentitiesOnly yes\n")
		// One name for the server's key, across every alias, so one known_hosts
		// line covers the whole project.
		fmt.Fprintf(&out, "    HostKeyAlias %s\n", in.hostKeyAlias)
		if in.knownHostsFile != "" {
			fmt.Fprintf(&out, "    UserKnownHostsFile %s\n", sshConfigPath(in.knownHostsFile))
		}
		if i < len(in.sandboxes)-1 {
			fmt.Fprintln(&out)
		}
	}
	return out.String()
}

func managedConfigHeader(projectID string) string {
	return "# Generated by `discobox admin ssh-config --write` for project " + projectID + ".\n" +
		"# This file is rewritten on every run: edit ~/.ssh/config instead, which\n" +
		"# Includes it.\n\n"
}

// writeManagedSSHConfig writes the stanzas and the server's host key where the
// target's ssh will look for them, then ensures that ssh's own config includes
// them.
//
// stanzas is empty when the project has no sandboxes, and that writes an empty
// config rather than skipping the write: these files mirror the server, so a
// project whose last sandbox is gone must stop offering stanzas for it.
func writeManagedSSHConfig(ctx context.Context, built managedSSHConfig, notes noteFunc) error {
	target := built.target
	configPath, knownHostsPath := target.configPath(built.namespace), target.knownHostsPath(built.namespace)
	if err := ensureStateDir(filepath.Dir(configPath.local)); err != nil {
		return fmt.Errorf("create SSH config directory: %w", err)
	}
	// Pinning the host key here rather than in ~/.ssh/known_hosts keeps
	// StrictHostKeyChecking meaningful without editing a file that records the
	// user's trust in every other host they use.
	knownHosts := ""
	if built.hostKey != "" {
		knownHosts = built.hostKeyAlias + " " + built.hostKey + "\n"
	}
	// 0600 like the config beside it: a known_hosts file is public
	// information, but nothing other than this user needs to read it.
	if err := os.WriteFile(knownHostsPath.local, []byte(knownHosts), 0o600); err != nil {
		return fmt.Errorf("write known_hosts: %w", err)
	}
	if err := os.WriteFile(configPath.local, []byte(managedConfigHeader(built.projectID)+built.stanzas), 0o600); err != nil {
		return fmt.Errorf("write SSH config: %w", err)
	}
	// Both files, every run, and not the directory holding them: ensureStateDir
	// restricts that where this process can, which across the WSL boundary is
	// nowhere, and ssh judges the file it opens rather than where it sits. A
	// run before this one may have left these readable by whoever the profile
	// grants — os.WriteFile over an existing file keeps the old DACL — and ssh
	// refuses a config it does not like the look of rather than ignoring it.
	// Across the boundary that judgement is Windows', and so is the ACL: a file
	// this process creates on a drive mount carries what WSL and the profile
	// put on it, and an Include ssh refuses is an Include that fails every host
	// in the user's config (sshTarget.restrict).
	//
	// A file this cannot vouch for is taken back, both of them together, for
	// the reason ADR 0102 §3 removes a mirrored key it cannot vouch for: the
	// caller carries on from this failure for an optional target, and what
	// would be left behind is an Include'd config ssh refuses — which fails
	// every host in the user's ssh_config, their own among them, where the
	// missing file an Include names is one ssh passes over without a word.
	for _, path := range []sshPath{knownHostsPath, configPath} {
		if err := target.restrict(ctx, path); err != nil {
			return errors.Join(
				fmt.Errorf("restrict %s to this user: %w", filepath.Base(path.local), err),
				removeFiles(configPath.local, knownHostsPath.local))
		}
	}

	edits, err := target.ensureUserConfigInclude(ctx, configPath)
	if err != nil {
		return err
	}
	retireLegacySSHConfig(ctx, built, notes)
	notes("wrote %s", configPath.client)
	rekeyManagedSSHConfigs(ctx, target, notes)
	if edits.added {
		notes("added an Include for it to %s", target.userConfig.client)
	}
	for _, stale := range edits.dropped {
		notes("removed a stale Include of %s", stale)
	}
	for _, repaired := range edits.repaired {
		notes("rewrote an Include of %s that ssh could not read", repaired)
	}
	if edits.unrestricted != nil {
		notes("could not narrow %s to the principals ssh reads it under: %v", target.userConfig.client, edits.unrestricted)
	}
	return nil
}

// rekeyManagedSSHConfigs is the upgrade of what an older CLI wrote into every
// project's managed config under this target: a stanza keyed by the discobox's
// name as well as its ID, or a comment naming a discobox whose every pattern
// was contested. A write rewrites only the project it is for, and another
// project's file can go unwritten for good — its server gone, the project never
// opened again — so each write re-keys the rest from what each stanza already
// says: its User is the ID, and its Host line becomes that ID's patterns
// (sshConfigHostPatterns). A file with nothing to re-key is not written. It
// runs under sshConfigLockName, so no other write of the same file falls
// between its read and its write.
//
// A rewritten file is restricted as the write above restricts its own: over an
// existing file os.WriteFile keeps whatever ACL an older CLI left, and ssh
// refuses an Included config it does not like the look of — failing every host
// in the user's ssh_config. Best-effort, like the Include repair: a file it
// cannot read, write or restrict is a note, and the write that called it
// stands.
func rekeyManagedSSHConfigs(ctx context.Context, target sshTarget, notes noteFunc) {
	paths, err := filepath.Glob(filepath.Join(target.sshDir().local, "*", "config"))
	if err != nil {
		return
	}
	for _, local := range paths {
		path := target.configPath(filepath.Base(filepath.Dir(local)))
		data, err := os.ReadFile(path.local)
		if err != nil {
			notes("could not read %s to re-key it by discobox ID: %v", path.client, err)
			continue
		}
		rekeyed, changed := rekeySSHConfigStanzas(string(data), filepath.Base(filepath.Dir(local)))
		if !changed {
			continue
		}
		if err := os.WriteFile(path.local, []byte(rekeyed), 0o600); err != nil {
			notes("could not re-key %s by discobox ID: %v", path.client, err)
			continue
		}
		if err := target.restrict(ctx, path); err != nil {
			notes("could not narrow %s to the principals ssh reads it under: %v", path.client, err)
		}
		notes("re-keyed %s by discobox ID", path.client)
	}
}

// retireLegacySSHConfig preserves another server's legacy project file. Only
// a generated file whose every route matches this rendering can be retired.
// Its Include stays valid and the file remains, with a migration note.
func retireLegacySSHConfig(ctx context.Context, built managedSSHConfig, notes noteFunc) {
	path := built.target.configPath(built.projectID)
	if path.local == built.target.configPath(built.namespace).local {
		return
	}
	data, err := os.ReadFile(path.local)
	if err != nil {
		return
	}
	if !strings.HasPrefix(string(data), managedConfigHeader(built.projectID)) {
		return
	}
	route := "    ProxyCommand " + escapeSSHPercent(built.proxyCommand)
	seen := false
	for _, line := range strings.Split(string(data), "\n") {
		if strings.HasPrefix(line, "    ProxyCommand ") {
			if line != route {
				return
			}
			seen = true
		}
	}
	if !seen {
		return
	}
	note := managedConfigHeader(built.projectID) + "# Stanzas moved to " + built.namespace + "/config.\n"
	if err := os.WriteFile(path.local, []byte(note), 0o600); err != nil {
		notes("could not retire legacy SSH config %s: %v", path.client, err)
		return
	}
	if err := built.target.restrict(ctx, path); err != nil {
		notes("could not restrict legacy SSH config %s: %v", path.client, err)
	}
}

// skippedStanzaSuffix ends the comment an older CLI wrote in place of a stanza
// whose every pattern another discobox's name had claimed.
const skippedStanzaSuffix = " has no unambiguous host alias and was skipped"

// rekeySSHConfigStanzas rewrites each stanza's Host line to its User's
// patterns, and drops the comments an older CLI left for a skipped discobox,
// reporting whether anything changed. A Host line with no User under it is
// none of this CLI's and is left as it is.
func rekeySSHConfigStanzas(config, namespace string) (string, bool) {
	lines := strings.Split(config, "\n")
	out := make([]string, 0, len(lines))
	host := -1
	changed := false
	for _, line := range lines {
		switch {
		case strings.HasPrefix(line, "# ") && strings.HasSuffix(line, skippedStanzaSuffix):
			changed = true
			continue
		case strings.HasPrefix(line, "Host "):
			host = len(out)
		case host >= 0 && strings.HasPrefix(line, "    User "):
			want := "Host " + strings.Join(sshConfigHostPatterns(namespace, strings.TrimPrefix(line, "    User ")), " ")
			if out[host] != want {
				out[host], changed = want, true
			}
			host = -1
		}
		out = append(out, line)
	}
	return strings.Join(out, "\n"), changed
}

// removeFiles takes back files this run wrote, reporting what it could not
// remove and passing over what is already gone.
func removeFiles(paths ...string) error {
	var errs []error
	for _, path := range paths {
		if err := os.Remove(path); err != nil && !os.IsNotExist(err) {
			errs = append(errs, fmt.Errorf("remove %s: %w", path, err))
		}
	}
	return errors.Join(errs...)
}

// includeEdits is what ensureUserConfigInclude did to a config the user owns,
// so the caller can say it: a line added, lines removed, lines rewritten under
// them.
type includeEdits struct {
	added bool
	// dropped are the Includes of files this CLI no longer writes.
	dropped []string
	// repaired are the Includes this CLI wrote before it escaped percent
	// signs, rewritten in the spelling ssh can read.
	repaired []string
	// unrestricted is why a config with no edit to make could not be narrowed
	// to the principals ssh reads it under. It is a note, not a failure.
	unrestricted error
}

func (e includeEdits) none() bool {
	return !e.added && len(e.dropped) == 0 && len(e.repaired) == 0
}

// ensureUserConfigInclude adds an Include for managed to the target ssh's
// config and normalizes the ones this CLI wrote, reporting what it did on each
// count. It is idempotent, so repeated runs leave one line rather than a
// growing pile.
//
// The line goes at the top because ssh_config takes the *first* value obtained
// for each keyword: an Include placed after a `Host *` block the user already
// has would lose every setting that block also sets.
//
// It runs under the target's userConfigLockName (lockUserConfig), which every
// install on the machine takes, so no other install's edit falls between its
// read and its rename.
func (t sshTarget) ensureUserConfigInclude(ctx context.Context, managed sshPath) (includeEdits, error) {
	release, err := t.lockUserConfig()
	if err != nil {
		return includeEdits{}, err
	}
	defer release()
	userConfig := t.userConfig.local
	existing, err := os.ReadFile(userConfig)
	if err != nil && !os.IsNotExist(err) {
		return includeEdits{}, fmt.Errorf("read %s: %w", userConfig, err)
	}
	cleaned, edits := t.normalizeManagedIncludes(string(existing), managed.client)
	edits.added = !t.hasInclude(cleaned, managed.client)
	if edits.none() {
		// A run with no edit to make did not rewrite that file, so nothing has
		// set its permissions since whatever last did — an older CLI, or this
		// one writing from the other side of a WSL boundary onto a drive mount
		// that hands out an ACL of its own. ssh reads it under the rule it
		// reads a key under and refuses every host in it over the answer, and
		// the Include that put the user in front of that file is ours, so each
		// run makes sure it is still one ssh will read. Under the lock, so it
		// narrows the file another install's rename has not yet replaced.
		//
		// Best-effort, unlike the write: this is a repair of a file that may
		// well need none, and a run that has already made a discobox does not
		// end over it (ADR 0102 §3).
		return includeEdits{unrestricted: t.restrict(ctx, t.userConfig)}, nil
	}
	body := cleaned
	if edits.added {
		body = "Include " + sshConfigPath(managed.client) + "\n"
		if len(cleaned) > 0 {
			body += "\n" + cleaned
		}
	}
	if err := t.writeUserConfig(ctx, body); err != nil {
		return includeEdits{}, err
	}
	return edits, nil
}

// userConfigLockName is the lock every edit of a target's ssh_config is made
// under. It sits beside that file rather than in a state directory because the
// file is shared by every install on the machine — a development build beside
// the release, each with its own state directory — while sshConfigLockName is
// one install's own. Each edit is a read, a prepend and a rename, and without a
// lock they all take, two installs editing at once each rename over the other
// and one install's Include is lost.
const userConfigLockName = ".discobox-ssh-config.lock"

// lockUserConfig takes userConfigLockName for an edit of the target's
// ssh_config and returns what lets go of it. It waits as long as a managed
// write does (sshConfigLockWait), since an edit across the WSL boundary
// restricts its file through Windows tools.
//
// A lock the filesystem will not give is no reason to lose the edit: a drive
// mount reached across the WSL boundary may not give one, and the race the
// lock closes costs an Include its install puts back on its next write. So
// any failure but another holder is passed over, and the edit goes ahead
// unlocked as it did before the lock existed; a directory the edit cannot
// write to is the write's own error to report.
func (t sshTarget) lockUserConfig() (release func(), err error) {
	dir := filepath.Dir(t.userConfig.local)
	if err := os.MkdirAll(dir, 0o700); err != nil {
		return nil, fmt.Errorf("create SSH directory: %w", err)
	}
	switch lock, err := acquireFileLock(filepath.Join(dir, userConfigLockName), sshConfigLockWait); {
	case err == nil:
		return func() { _ = lock.Release() }, nil
	case errors.Is(err, filelock.ErrBusy):
		return nil, fmt.Errorf("another discobox command is still editing %s; try again", t.userConfig.client)
	default:
		return func() {}, nil
	}
}

// writeUserConfig replaces the target ssh's config with body. The caller
// holds lockUserConfig.
func (t sshTarget) writeUserConfig(ctx context.Context, body string) error {
	userConfig := t.userConfig.local
	if err := os.MkdirAll(filepath.Dir(userConfig), 0o700); err != nil {
		return fmt.Errorf("create SSH directory: %w", err)
	}
	// Written through a temp file in the same directory so an interrupted run
	// cannot leave the user with a truncated ssh_config.
	tmp, err := os.CreateTemp(filepath.Dir(userConfig), ".discobox-ssh-config-*")
	if err != nil {
		return fmt.Errorf("write %s: %w", userConfig, err)
	}
	defer os.Remove(tmp.Name())
	// Chmod is the whole story on Unix and none of it on Windows, where the
	// file this replaces is one ssh reads and checks. A file this process
	// creates on a mounted Windows drive has no mode at all — the mount does not
	// carry one — and an ACL it inherited from the directory, which is the ACL
	// ssh refuses. So the mode is set where there is one to set and the ACL
	// where only Windows can set it, and both happen before the rename: what
	// lands in the user's ssh_config is already a file ssh will read.
	if err := tmp.Chmod(0o600); err != nil && !t.acrossWSL() {
		_ = tmp.Close()
		return fmt.Errorf("write %s: %w", userConfig, err)
	}
	if err := t.restrict(ctx, t.join(t.dir(t.userConfig), filepath.Base(tmp.Name()))); err != nil {
		_ = tmp.Close()
		return fmt.Errorf("write %s: %w", userConfig, err)
	}
	if _, err := tmp.WriteString(body); err != nil {
		_ = tmp.Close()
		return fmt.Errorf("write %s: %w", userConfig, err)
	}
	if err := tmp.Close(); err != nil {
		return fmt.Errorf("write %s: %w", userConfig, err)
	}
	if err := os.Rename(tmp.Name(), userConfig); err != nil {
		return fmt.Errorf("write %s: %w", userConfig, err)
	}
	return nil
}

// normalizeManagedIncludes brings the Include lines this CLI owns into the
// state this run writes them in: the ones naming a file it no longer writes are
// removed, and the ones written before it escaped percent signs are rewritten
// in the spelling ssh can read. It returns the config and what it did to it.
//
// Removing the stale ones is not tidiness. ssh fails outright on an Include it
// will not read — one whose permissions it dislikes, in particular — so a line
// left pointing into a directory this CLI has moved out of breaks every
// connection through this config, including the ones the new line was written
// to make work.
//
// The repair is the same failure reached the other way. A line written before
// escapeSSHPercent existed names a file ssh cannot expand, and ssh abandons the
// whole config over it rather than that one line: until it is rewritten no host
// in the file resolves, this CLI's or anyone else's. Matching an Include on the
// filename it names is what keeps a run from duplicating its own line, and it
// is also what would leave this one sitting there forever, since the file it
// names is the file this run would name.
//
// It is rewritten rather than dropped because the file it names is still the
// right one: the line may belong to another project, which this run cannot
// re-add and whose own next run may be a long way off.
//
// A managed path is recognized by its shape — <anything>/discobox/cli/ssh/<project>/config
// — which is what this CLI has always written and nothing else has reason to.
// Anything matching that shape and sitting outside the current state directory
// was written by an older version that kept its state somewhere else, and is
// now a path with nothing behind it or, worse, a file whose permissions ssh
// refuses. Includes under the current state directory are left alone however
// many there are: one per project is the design.
//
// The user's own Includes are untouched. Only this shape is ours to edit.
func (t sshTarget) normalizeManagedIncludes(config, managed string) (string, includeEdits) {
	var kept []string
	var edits includeEdits
	for _, line := range strings.Split(config, "\n") {
		field, ok := t.includeField(line)
		filename := unescapeSSHPercent(field)
		path := t.clean(filename)
		switch {
		case !ok || !t.isManagedConfigPath(path):
			kept = append(kept, line)
		case !t.samePathAs(path, managed) && !t.within(t.state.client, path):
			edits.dropped = append(edits.dropped, path)
		case field != escapeSSHPercent(filename):
			edits.repaired = append(edits.repaired, path)
			kept = append(kept, "Include "+sshConfigPath(filename))
		default:
			kept = append(kept, line)
		}
	}
	if len(edits.dropped) == 0 && len(edits.repaired) == 0 {
		return config, edits
	}
	body := strings.Join(kept, "\n")
	if len(edits.dropped) > 0 {
		// A dropped line leaves a blank behind, and a run of them accumulates:
		// the file is rewritten without the gaps rather than growing one per
		// removal.
		body = collapseBlankRuns(body)
	}
	return body, edits
}

// includeField is the path an Include line names, if the line is one, spelled
// as the line spells it — percent escapes and all. What ssh opens is
// unescapeSSHPercent of it.
func (t sshTarget) includeField(line string) (string, bool) {
	trimmed := strings.TrimSpace(line)
	if trimmed == "" || strings.HasPrefix(trimmed, "#") {
		return "", false
	}
	fields := sshConfigFields(trimmed)
	// Exactly one path: an Include naming several files is not one of ours, and
	// picking one of them out of it would be rewriting a line we did not write.
	if len(fields) != 2 || !strings.EqualFold(fields[0], "include") {
		return "", false
	}
	return fields[1], true
}

// isManagedConfigPath reports whether path has the shape this CLI writes:
// .../discobox/cli/ssh/<project>/config.
func (t sshTarget) isManagedConfigPath(p string) bool {
	cleaned := t.clean(p)
	slash := strings.LastIndex(cleaned, "/")
	if slash < 0 || !strings.EqualFold(cleaned[slash+1:], "config") {
		return false
	}
	parts := strings.Split(cleaned[:slash], "/")
	if len(parts) < 4 {
		return false
	}
	tail := parts[len(parts)-4:]
	return strings.EqualFold(tail[0], "discobox") &&
		strings.EqualFold(tail[1], "cli") &&
		strings.EqualFold(tail[2], "ssh")
}

// collapseBlankRuns leaves at most one blank line where there were several, so
// removing lines from the middle of a config does not leave it full of holes.
func collapseBlankRuns(config string) string {
	var out []string
	blank := false
	for _, line := range strings.Split(config, "\n") {
		if strings.TrimSpace(line) == "" {
			if blank {
				continue
			}
			blank = true
		} else {
			blank = false
		}
		out = append(out, line)
	}
	return strings.Join(out, "\n")
}

// hasInclude reports whether config already includes managed, matching on the
// path rather than the whole line so an Include the user reformatted (extra
// spacing, quotes) is still recognized and not duplicated.
func (t sshTarget) hasInclude(config, managed string) bool {
	scanner := bufio.NewScanner(strings.NewReader(config))
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		fields := sshConfigFields(line)
		if len(fields) < 2 || !strings.EqualFold(fields[0], "include") {
			continue
		}
		for _, field := range fields[1:] {
			if t.samePathAs(unescapeSSHPercent(field), managed) {
				return true
			}
		}
	}
	return false
}

// sshConfigFields splits an ssh_config line the way OpenSSH reads the lines
// this CLI writes: whitespace-separated, with double quotes holding a value
// containing a space together. Plain strings.Fields would do everywhere but
// Windows, where a profile under a user whose name has a space in it — "C:\
// Users\Ada Lovelace\…" — is an ordinary path to have to name.
func sshConfigFields(line string) []string {
	var fields []string
	var current strings.Builder
	quoted, started := false, false
	for _, r := range line {
		switch {
		case r == '"':
			quoted = !quoted
			started = true
		case !quoted && (r == ' ' || r == '\t'):
			if started {
				fields = append(fields, current.String())
				current.Reset()
				started = false
			}
		default:
			current.WriteRune(r)
			started = true
		}
	}
	if started {
		fields = append(fields, current.String())
	}
	return fields
}

// sshConfigPath renders a path the way an ssh_config has to spell it: percent
// escaped, and wrapped in the double quotes ssh needs when it contains a space
// — a Windows profile under a name with a space in it, "C:\Users\Ada Lovelace\…",
// is an ordinary path. A path with neither is left alone, so the ordinary line
// stays the one people have always seen.
func sshConfigPath(path string) string {
	escaped := escapeSSHPercent(path)
	if !strings.ContainsAny(escaped, " \t") {
		return escaped
	}
	return `"` + escaped + `"`
}

// escapeSSHPercent doubles every percent sign, which is how a literal one is
// written in a value ssh expands tokens in.
//
// ssh expands %h, %p, %r and the rest in ProxyCommand, IdentityFile,
// UserKnownHostsFile and Include, and an unknown key there is not ignored: it
// fails the expansion, and with it the whole connection, with
// "percent_expand: failed" and no indication of which line was at fault.
//
// This is not a hypothetical %z. An iroh endpoint carrying direct addresses
// spells them as query parameters — iroh://<id>?addr=192.0.2.7%3A11204 — and
// the ProxyCommand carries whatever endpoint the config was written against,
// so pointing the CLI at a remote host is precisely the case that produces
// one.
func escapeSSHPercent(value string) string {
	return strings.ReplaceAll(value, "%", "%%")
}

// unescapeSSHPercent reads back what escapeSSHPercent wrote, so an Include this
// CLI put in the user's config is recognized as naming the file it names rather
// than as a second, differently spelled one.
func unescapeSSHPercent(value string) string {
	return strings.ReplaceAll(value, "%%", "%")
}

// concreteProjectID turns whatever -p was given into the project's real ID.
//
// It is deliberately not id.go's resolveProjectID, which passes the "default"
// alias through untouched for the server to resolve. That is right for a
// request — the server is the only side that knows which project carries the
// default flag — and wrong here: these files are *named* after the project, so
// leaving the alias unresolved is exactly how one project ends up owning two
// files and two Include lines.
func (a *App) concreteProjectID(ctx context.Context, client *apiclientgen.Client, projectID string) (string, error) {
	res, err := client.GetProject(ctx, apiclientgen.GetProjectParams{ProjectId: projectID})
	if err != nil {
		return "", err
	}
	project, err := expectResponse[apimodel.Project](res)
	if err != nil {
		return "", err
	}
	if strings.TrimSpace(project.ID) == "" {
		return "", fmt.Errorf("server returned no ID for project %q", projectID)
	}
	return project.ID, nil
}
